package kz.zani.mobile

import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class TaskCreateAppointmentTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun catalog()=JSONObject(fixture("task-create-appointment-cases"))
    private val context=TaskDraftContext(101,1)
    private fun detail()=JsonContracts.detail(fixture("appointment-101-501"))
    private fun choice()=TaskDraftAppointmentChoice.make(detail(),101,501)!!
    private class Reads:AgendaRepository {
        val calls=mutableListOf<String>();val lists=mutableListOf<CompletableDeferred<AppointmentList>>();val details=mutableListOf<CompletableDeferred<AppointmentDetail>>()
        override suspend fun bootstrap():Bootstrap=error("No bootstrap in manual Task picker")
        override suspend fun appointments(business:Int,day:String):AppointmentList {calls+="list:$business:$day";return CompletableDeferred<AppointmentList>().also {lists+=it}.await()}
        override suspend fun appointment(business:Int,id:Int):AppointmentDetail {calls+="detail:$business:$id";return CompletableDeferred<AppointmentDetail>().also {details+=it}.await()}
    }
    private class Port:SyntheticTaskCreatePort {
        override val grants=listOf(SyntheticTaskCreateGrant(101,9001,true));val calls=mutableListOf<TaskCreateAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticTaskCreateOutcome>>()
        override suspend fun execute(attempt:TaskCreateAttempt):SyntheticTaskCreateOutcome {calls+=attempt;return CompletableDeferred<SyntheticTaskCreateOutcome>().also {pending+=it}.await()}
    }
    private fun fill(m:TaskDraftModel) {m.bind(context);m.open(context);m.update(TaskDraftField.TITLE,"  Visit task\n",m.inputControl);m.update(TaskDraftField.DESCRIPTION,"  Raw notes\n",m.inputControl);m.chooseDue(TaskDraftDueMode.SET,m.inputControl);m.update(TaskDraftField.DUE_AT,"2026-11-02T09:30:00+05:00",m.inputControl);m.chooseReminder(TaskDraftDueMode.SET,m.inputControl);m.update(TaskDraftField.REMINDER_AT,"2026-11-01T14:00:00Z",m.inputControl)}
    private fun page(i:Int=0)=JsonContracts.appointments(catalog().getJSONArray("page_cases").getJSONObject(i).getString("page_json"))
    private fun check(block:suspend TestScope.(TaskDraftModel,Port,Reads)->Unit)=runTest {val reads=Reads();val port=Port();val m=TaskDraftModel(port,this,appointments=reads);fill(m);try {block(m,port,reads)}finally {m.bind(null)}}
    private fun TestScope.list(m:TaskDraftModel,r:Reads) {m.openAppointmentPicker(m.inputControl);val read=m.appointments!!;read.updateDay("2026-10-30",read.control);read.read(read.control);runCurrent();r.lists.last().complete(page());runCurrent()}
    private fun TestScope.select(m:TaskDraftModel,r:Reads) {list(m,r);val read=m.appointments!!;read.open(501,read.control);runCurrent();r.details.last().complete(detail());runCurrent();m.confirmAppointment(m.appointmentPickerOwner,read.control)}
    @Test fun sharedDateInputRejectsClockAndNormalization() {val rows=catalog().getJSONArray("day_cases");for(i in 0 until rows.length()){val row=rows.getJSONObject(i);assertEquals(row.getString("day"),row.getBoolean("valid"),TaskAppointmentDay.valid(row.getString("day")))}}
    @Test fun sharedIndependentDetailIdentityAndNoEligibilityInference() {val rows=catalog().getJSONArray("choice_cases");for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val d=JsonContracts.detail(row.getString("detail_json"));val v=TaskDraftAppointmentChoice.make(d,row.getInt("business"),row.getInt("id"));assertEquals(row.getString("name"),row.getBoolean("valid"),v!=null);if(v!=null){assertEquals(d.appointment.title,v.title);assertEquals(d.appointment.startAt,v.startAt);assertEquals(d.appointment.status,v.status)}}}
    @Test fun genericFkReceiptDoesNotAliasBoundedGetOrPromoteUnselected() {
        val rows=catalog().getJSONArray("receipt_cases");val auth=SyntheticTaskCreateGrant(101,9001,true).authorization(context)!!
        for(i in 0 until rows.length()) {val row=rows.getJSONObject(i);val s=TaskDraftSession();s.bind(context);s.open(context);val q=s.state.selection!!;s.update(TaskDraftField.TITLE,"Manual task",q);s.update(TaskDraftField.DESCRIPTION,"Raw notes",q);if(!row.isNull("selected"))s.chooseAppointment(choice(),q);assertTrue(s.prepare(q));val ledger=TaskCreateAttemptLedger();val a=ledger.begin(s.state.review!!,auth)!!;val body=JSONObject(a.preparedBody()!!);assertFalse(body.has("appointment_id"));assertEquals(!row.isNull("selected"),body.has("appointment"));val read=TaskCreateAppointmentRead.decode(row.getString("body_json"));assertEquals(when(row.getString("kind")){"appointment"->TaskCreateAppointmentRead.Appointment(row.getInt("id"));"notSet"->TaskCreateAppointmentRead.NotSet;else->TaskCreateAppointmentRead.Unknown},read)
            val v=a.review.preview;val t=WorkTask(88001,v.title,"open",v.priority,null,business=101,description=v.description,createdBy=9001,createdAt="2026-10-30T12:00:00Z",updatedAt="2026-10-30T12:00:00Z");ledger.complete(a,SyntheticTaskCreateOutcome.Response(row.getInt("status"),t,appointmentRead=read));val yes=row.getBoolean("accepted");assertEquals(row.getString("name"),yes,ledger.visible(auth)!!.phase==TaskCreateAttemptPhase.CONFIRMED);assertEquals(if(yes && !row.isNull("selected"))501 else null,ledger.visible(auth)!!.appointmentID);if(!yes){assertFalse(ledger.acknowledge(auth));assertNull(ledger.begin(a.review,auth));assertEquals(a.preparedBody(),ledger.records.single().attempt.preparedBody())}
        }
    }
    @Test fun noDefaultDateOrReadAndOldParentInputInactive()=check {m,_,r->val raw=m.state.values;val input=m.inputControl;val old=m.control;m.openAppointmentPicker(input);assertEquals("",m.appointments!!.state.day);assertFalse(m.appointments.canRead);assertTrue(r.calls.isEmpty());assertNull(m.inputControl);m.update(TaskDraftField.TITLE,"overwrite",input);m.prepare(old);m.openClientPicker(input);assertEquals(raw,m.state.values);assertNull(m.clientPickerOwner)}
    @Test fun listCountsScopeUniquenessAndCapRemainTruthful()=check {m,_,r->m.openAppointmentPicker(m.inputControl);val read=m.appointments!!;read.updateDay("2026-10-30",read.control);val rows=catalog().getJSONArray("page_cases");for(i in 0 until rows.length()){read.read(read.control);runCurrent();val pending=read.control;r.lists.last().complete(page(i));runCurrent();val valid=rows.getJSONObject(i).getBoolean("valid");assertEquals(valid,read.state.loaded);assertNotEquals(pending,read.control);if(valid){assertEquals(page(i).items,read.state.items);assertEquals(page(i).total,read.state.total);assertEquals(page(i).total>page(i).items.size,read.state.partial)}}}
    @Test fun currentListIsRequiredAndPendingDetailCannotChoose()=check {m,_,r->list(m,r);val read=m.appointments!!;read.open(999999,read.control);assertNull(read.state.selectedID);read.open(501,read.control);runCurrent();m.confirmAppointment(m.appointmentPickerOwner,read.control);assertNull(m.state.values.appointment);r.details.last().complete(detail());runCurrent()}
    @Test fun closeAndReopenQuarantineLateListAndOldOwner()=check {m,_,r->val raw=m.state.values;m.openAppointmentPicker(m.inputControl);val owner=m.appointmentPickerOwner;val read=m.appointments!!;read.updateDay("2026-10-30",read.control);read.read(read.control);runCurrent();val old=read.control;m.closeAppointmentPicker(owner);m.openAppointmentPicker(m.inputControl);r.lists.last().complete(page());runCurrent();m.confirmAppointment(owner,old);assertEquals(raw,m.state.values);assertEquals("",read.state.day);assertFalse(read.state.loaded)}
    @Test fun backQuarantinesLateDetailAndRetainsExplicitList()=check {m,_,r->list(m,r);val read=m.appointments!!;read.open(501,read.control);runCurrent();read.backDetail(read.control);val back=read.control;r.details.last().complete(detail());runCurrent();assertEquals(back,read.control);assertNull(read.state.detail);assertTrue(read.state.loaded);assertEquals("2026-10-30",read.state.day)}
    @Test fun foreignDetailThenExplicitRetryRequiresCompletedControl()=check {m,_,r->list(m,r);val read=m.appointments!!;read.open(501,read.control);runCurrent();r.details.last().complete(JsonContracts.detail(fixture("appointment-202-601")));runCurrent();assertEquals(ReadProblem.INVALID_PAYLOAD,read.state.problem);read.retryDetail(read.control);runCurrent();val old=read.control;r.details.last().complete(detail());runCurrent();m.confirmAppointment(m.appointmentPickerOwner,old);assertNull(m.state.values.appointment);m.confirmAppointment(m.appointmentPickerOwner,read.control);assertEquals(501,m.state.values.appointment!!.id)}
    @Test fun validChoiceAndRemovalRetainAllRawDatesAndText()=check {m,_,r->val raw=m.state.values;select(m,r);assertEquals(raw.copy(appointment=choice()),m.state.values);m.clearAppointment(m.inputControl);assertEquals(raw,m.state.values);m.prepare(m.control);assertNull(m.state.review!!.preview.appointmentID)}
    @Test fun unknownRetainsExactRelationBodyAndBlocksEditClearAndEpochReplay()=check {m,p,r->select(m,r);val input=m.inputControl;m.prepare(m.control);val review=m.state.review!!;m.launchSubmit(review,m.control);runCurrent();val a=p.calls.single();val body=a.preparedBody();p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();m.clearAppointment(input);m.openAppointmentPicker(input);m.discard(review.selection);assertEquals(review.values,m.state.values);assertEquals(body,m.submission!!.attempt.preparedBody());assertEquals(TaskCreateAttemptPhase.UNKNOWN,m.submission!!.phase);m.bind(TaskDraftContext(101,2));m.open(TaskDraftContext(101,2));assertTrue(m.submissionBlocked);assertNull(m.submission);assertEquals(1,m.retainedAttemptCount);assertEquals(1,p.calls.size)}
    @Test fun changedBusinessQuarantinesPendingRead()=check {m,_,r->list(m,r);val read=m.appointments!!;val owner=m.appointmentPickerOwner;read.open(501,read.control);runCurrent();val old=read.control;m.bind(TaskDraftContext(202,2));r.details.last().complete(detail());runCurrent();m.confirmAppointment(owner,old);assertNull(m.state.values.appointment);assertNull(read.state.context)}
    @Test fun existingSafeReadFeedbackPreservesDeniedAndNotFoundInAllLocales() {val states=mapOf("denied" to ReadProblem.DENIED,"not_found" to ReadProblem.NOT_FOUND,"unavailable" to ReadProblem.UNAVAILABLE,"invalid_payload" to ReadProblem.INVALID_PAYLOAD,"invalid_context" to ReadProblem.INVALID_CONTEXT);val rows=catalog().getJSONArray("read_feedback_cases");val copy=JSONObject(javaClass.classLoader!!.getResourceAsStream("ui-copy.json")!!.bufferedReader().use {it.readText()});for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val key=TaskAppointmentReadFeedback.copyKey(states.getValue(row.getString("problem")));assertEquals(row.getString("copy_key"),key);for(lang in listOf("ru","kk","en"))assertTrue(copy.getJSONObject(lang).getString(key).isNotBlank())}}
    @Test fun defaultNoScopeDoesNotInventReadOwner() {val m=TaskDraftModel(appointments=Reads());fill(m);m.openAppointmentPicker(m.inputControl);assertFalse(m.appointmentPickerAvailable);assertNull(m.appointmentPickerOwner)}
    @Test fun consecutiveDateInputSurvivesRawChangesButNotReadDetailBackOrEpoch()=runTest {
        val r=Reads();val m=TaskAppointmentPickerModel(r,this);m.begin(context);val input=m.inputControl!!;val staleRead=m.control
        for(raw in listOf("2","20","2026-10-30")){m.updateDay(raw,input=input);assertEquals(raw,m.state.day);assertEquals(input,m.inputControl)}
        m.read(staleRead);runCurrent();assertTrue(r.calls.isEmpty());m.read(m.control);runCurrent();m.updateDay("overwrite",input=input);assertNull(m.inputControl);assertEquals("2026-10-30",m.state.day)
        r.lists.single().complete(page());runCurrent();val after=m.inputControl!!;m.updateDay("overwrite",input=input);assertEquals("2026-10-30",m.state.day);assertNotEquals(input,after)
        m.open(501,m.control);runCurrent();assertNull(m.inputControl);m.backDetail(m.control);val back=m.inputControl!!;m.updateDay("overwrite",input=after);assertEquals("2026-10-30",m.state.day);assertNotEquals(after,back)
        r.details.single().complete(detail());runCurrent();assertNull(m.state.detail);assertEquals(back,m.inputControl);m.begin(TaskDraftContext(101,2));m.updateDay("overwrite",input=back);assertTrue(m.state.day.isEmpty());assertNotEquals(back,m.inputControl)
    }
}
